"""Lazy Native route policy for four exact C109705 departure settings.

The map survey and source hash must come from an actual reviewed Native map.
No local map or CARLA execution is implied by this CPU-checkable policy.
"""
from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path

ASSIGNMENT = 'testing__C109705__NRS-484B-400-2b__motor_vehicle_driver'
SUFFIXES = ('near_centerline', 'farther_from_centerline',
            'imaginary_near_centerline', 'imaginary_farther_from_centerline')


def _point(value):
    if not isinstance(value, list) or len(value) != 2 or not all(type(v) in (int, float) and math.isfinite(v) for v in value):
        raise ValueError('finite map point required')
    return float(value[0]), float(value[1])


def _unit(a, b):
    dx, dy = b[0] - a[0], b[1] - a[1]
    length = math.hypot(dx, dy)
    if length < 1:
        raise ValueError('degenerate surveyed lane direction')
    return dx / length, dy / length


def _check_road(road):
    if road.get('alley') is not False or road.get('public_highway_source') is None or not road.get('road_id'):
        raise ValueError('sourced non-alley highway identity required')
    lanes = road.get('permitted_lanes')
    if not isinstance(lanes, list) or len(lanes) < 2:
        raise ValueError('opposed permitted lanes missing')
    directions = [_unit(_point(lane['from_xy_m']), _point(lane['to_xy_m'])) for lane in lanes]
    if not any(sum(x * y for x, y in zip(a, b)) < -0.95 for a in directions for b in directions):
        raise ValueError('road is not shown two directional')
    return road['road_id']


def build(case_id, map_survey, *, map_source_path=None):
    if case_id not in {ASSIGNMENT + '__' + suffix for suffix in SUFFIXES}:
        raise ValueError('case differs from exact assignment')
    suffix = case_id.rsplit('__', 1)[1]
    if map_survey.get('cell_id') != 'C109705' or map_survey.get('maneuver') != 'left_turn':
        raise ValueError('wrong cell or maneuver')
    roads = map_survey.get('intersecting_roads')
    if not isinstance(roads, list) or len(roads) != 2:
        raise ValueError('both intersecting roads required')
    ids = {_check_road(road) for road in roads}
    if {map_survey.get('approach_road_id'), map_survey.get('destination_road_id')} != ids:
        raise ValueError('disconnected approach/destination roads')
    kind = 'source_derived_imaginary' if suffix.startswith('imaginary_') else 'mapped'
    if map_survey.get('destination_centerline_kind') != kind:
        raise ValueError('destination centerline convention differs')
    if kind == 'source_derived_imaginary' and not map_survey.get('imaginary_line_derivation_source'):
        raise ValueError('imaginary line requires source derivation')
    line = map_survey.get('destination_centerline_xy_m')
    if not isinstance(line, list) or len(line) != 2:
        raise ValueError('destination centerline endpoints required')
    a, b = _point(line[0]), _point(line[1])
    direction = _unit(a, b)
    half_width = map_survey.get('destination_half_width_m')
    if type(half_width) not in (float, int) or half_width <= 2.7:
        raise ValueError('destination right half width missing')
    route = map_survey.get('left_turn_route_waypoint_ids')
    if not isinstance(route, list) or len(route) < 3 or not map_survey.get('ego_blueprint_id'):
        raise ValueError('connected left-turn route or vehicle blueprint missing')
    if not map_survey.get('map_name') or not map_survey.get('approach_policy'):
        raise ValueError('map name or fixed approach policy missing')
    if map_survey.get('camera_plan') is None:
        raise ValueError('four-camera plan missing')
    if map_source_path is not None:
        actual = hashlib.sha256(Path(map_source_path).read_bytes()).hexdigest()
        if actual != map_survey.get('source_sha256'):
            raise ValueError('source-hashed Native map differs')
    elif not map_survey.get('source_sha256'):
        raise ValueError('Native map survey hash missing')
    # Distances are engineering targets for the contrast, not statutory cutoffs.
    offset = 1.7 if suffix.endswith('near_centerline') else 2.7
    right = direction[1], -direction[0]
    departure_target = [b[0] + offset * right[0], b[1] + offset * right[1]]
    return {
        'case_id':case_id,
        'map_name':map_survey.get('map_name'),
        'survey_source_sha256':map_survey['source_sha256'],
        'ego_blueprint_id':map_survey['ego_blueprint_id'],
        'left_turn_route_waypoint_ids':route,
        'approach_policy':map_survey.get('approach_policy'),
        'departure_target_xy_m':departure_target,
        'departure_target_offset_m':offset,
        'controller_policy':{'target_speed_mps':7.0,'steer_gain':0.45,'brake_on_route_end':True},
        'camera_plan':map_survey['camera_plan'],
        'duration_s':45,'rate_hz':20,
        'legal_lateral_cutoff':None,
    }


def control(position_xy_m, heading_rad, target_xy_m, speed_mps, *, target_speed_mps=7.0):
    vals = (*position_xy_m, heading_rad, *target_xy_m, speed_mps, target_speed_mps)
    if any(type(v) not in (int, float) or not math.isfinite(v) for v in vals):
        raise ValueError('nonfinite control sample')
    if speed_mps < 0 or target_speed_mps <= 0:
        raise ValueError('invalid speed')
    dx, dy = target_xy_m[0] - position_xy_m[0], target_xy_m[1] - position_xy_m[1]
    if math.hypot(dx, dy) < 0.5:
        return {'throttle':0.0,'brake':1.0,'steer':0.0}
    error = (math.atan2(dy, dx) - heading_rad + math.pi) % (2 * math.pi) - math.pi
    return {'throttle':max(0.0,min(0.35,(target_speed_mps - speed_mps) * 0.1)),
            'brake':max(0.0,min(1.0,(speed_mps - target_speed_mps) * 0.2)),
            'steer':max(-1.0,min(1.0,0.45 * error))}


def main():
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument('--case', required=True)
    parser.add_argument('--map-survey', required=True)
    parser.add_argument('--output', required=True)
    args = parser.parse_args()
    path = Path(args.map_survey)
    survey = json.loads(path.read_text())
    source = survey.get('map_source_path')
    if not source:
        raise ValueError('Native map source path missing')
    result = build(args.case, survey, map_source_path=path.parent / source)
    Path(args.output).write_text(json.dumps(result, indent=2) + '\n')


if __name__ == '__main__':
    main()

"""Lazy Native capture contract for the four exact departure cases.

The caller supplies a CARLA adapter; importing this module does not import CARLA.
All packet fields come from adapter readback, rather than requested targets.
"""
from __future__ import annotations

import hashlib
import importlib.util
import json
import math
from pathlib import Path

HERE = Path(__file__).resolve().parent
spec = importlib.util.spec_from_file_location('departure_route_policy', HERE / 'construction.py')
route_policy = importlib.util.module_from_spec(spec)
spec.loader.exec_module(route_policy)

CAMERAS = ('dash', 'front', 'left', 'right')


def _point(value, name):
    if not isinstance(value, (list, tuple)) or len(value) != 2:
        raise ValueError(f'{name} must be an xy pair')
    if any(type(x) not in (int, float) or not math.isfinite(x) for x in value):
        raise ValueError(f'{name} must be finite')
    return [float(value[0]), float(value[1])]


def _state(raw, frame, previous_frame, expected_case):
    if raw.get('case_id') != expected_case:
        raise ValueError('Native ego case readback differs')
    if raw.get('frame') != frame or frame != previous_frame + 1:
        raise ValueError('Native ego frame gap or mismatch')
    position = _point(raw.get('position_xy_m'), 'ego position')
    corners = raw.get('body_corners_xy_m')
    if not isinstance(corners, list) or len(corners) < 4:
        raise ValueError('Native full body corners missing')
    corners = [_point(c, 'body corner') for c in corners]
    heading, speed = raw.get('heading_rad'), raw.get('speed_mps')
    if any(type(x) not in (int, float) or not math.isfinite(x) for x in (heading, speed)) or speed < 0:
        raise ValueError('Native heading or speed invalid')
    phase = raw.get('phase')
    if phase not in ('approach', 'intersection_entry', 'turning', 'departure'):
        raise ValueError('Native route phase missing')
    if not isinstance(raw.get('road_id'), (str, int)):
        raise ValueError('Native road ID missing')
    if raw.get('driver_control') is not True:
        raise ValueError('Native driver control missing')
    elapsed = raw.get('elapsed_seconds')
    if type(elapsed) not in (int, float) or not math.isfinite(elapsed) or elapsed < 0:
        raise ValueError('Native original elapsed clock missing')
    return {'frame': frame, 'phase': phase, 'road_id': raw['road_id'],
            'position_xy_m': position, 'body_corners_xy_m': corners,
            'heading_rad': float(heading), 'speed_mps': float(speed),
            'elapsed_seconds': float(elapsed)}


def capture(adapter, case_id, survey, map_source_path, output_dir, *, camera_source=None):
    """Execute a 45 s, 20 Hz capture using an injected synchronous Native adapter.

    Adapter methods: spawn_ego, configure_cameras, resolve_waypoint, apply_control,
    tick, ego_snapshot, camera_frame, emergency_stop, destroy. A camera_frame
    returns metadata for an original retained frame with its source path; it may
    not substitute a generated image or an absent frame.
    """
    plan = route_policy.build(case_id, survey, map_source_path=map_source_path)
    if tuple(plan['camera_plan']) != CAMERAS:
        raise ValueError('four exact camera channels required')
    output = Path(output_dir)
    if output.is_symlink():
        raise ValueError('refusing symlinked Native capture')
    for name in ('original-trace.json', 'original-camera-index.json',
                 'original-cameras', 'original-map.xodr',
                 'original-map-packet.json', 'source-manifest.json',
                 'original-bindings.json', 'acquisition.json',
                 'capture-seal.json', 'trace.jsonl', 'video_frames.jsonl'):
        if (output / name).exists() or (output / name).is_symlink():
            raise ValueError('refusing to overwrite original Native capture')
    if camera_source is not None and Path(camera_source.output).resolve().parent != output.resolve():
        raise ValueError('original camera sources must be attempt local')
    output.mkdir(parents=True, exist_ok=True)
    ego = None
    samples = []
    cameras = {name: [] for name in CAMERAS}
    previous_frame = None
    waypoint_index = 0
    entered = departed = False
    try:
        ego = adapter.spawn_ego(plan['ego_blueprint_id'], survey['map_name'], case_id)
        if camera_source is None:
            adapter.configure_cameras(ego, CAMERAS, fps=20)
        else:
            camera_source.configure_cameras(ego, CAMERAS, fps=20)
        for tick_index in range(900):
            waypoint_ids = plan['left_turn_route_waypoint_ids']
            if waypoint_index < len(waypoint_ids):
                target = _point(adapter.resolve_waypoint(waypoint_ids[waypoint_index]), 'Native waypoint')
            else:
                target = plan['departure_target_xy_m']
            if samples:
                prior = samples[-1]
                command = route_policy.control(prior['position_xy_m'], prior['heading_rad'], target,
                                               prior['speed_mps'])
            else:
                command = {'throttle': 0.0, 'brake': 1.0, 'steer': 0.0}
            adapter.apply_control(ego, command)
            frame = adapter.tick()
            if type(frame) is not int or (previous_frame is not None and frame != previous_frame + 1):
                raise ValueError('Native tick frame discontinuity')
            raw = adapter.ego_snapshot(ego, frame)
            sample = _state(raw, frame, previous_frame if previous_frame is not None else frame - 1, case_id)
            if samples and abs(sample['elapsed_seconds'] - samples[0]['elapsed_seconds'] - tick_index / 20) > 0.002:
                raise ValueError('Native original 20 Hz clock drift')
            if sample['phase'] == 'turning' and not entered:
                raise ValueError('Native turn began before observed intersection entry')
            if sample['phase'] == 'intersection_entry':
                if departed:
                    raise ValueError('Native route returned to intersection after departure')
                entered = True
            if sample['phase'] == 'departure':
                if not entered or sample['road_id'] != survey['destination_road_id']:
                    raise ValueError('departure lacks observed entry or destination road')
                departed = True
            if sample['phase'] != 'departure' and departed:
                raise ValueError('Native route regressed after departure')
            samples.append(sample)
            for name in CAMERAS:
                camera = (adapter.camera_frame(name, frame) if camera_source is None
                          else camera_source.camera_frame(name, frame))
                if not isinstance(camera, dict) or camera.get('frame') != frame or camera.get('channel') != name:
                    raise ValueError('Native four-camera frame missing or unsynchronized')
                if not camera.get('source_path') or not camera.get('source_sha256'):
                    raise ValueError('Native camera source binding missing')
                cameras[name].append(camera)
            if math.dist(sample['position_xy_m'], target) < 0.5 and waypoint_index < len(waypoint_ids):
                waypoint_index += 1
            previous_frame = frame
        if not entered or not departed:
            raise ValueError('Native original trace lacks intersection entry or departure')
        if math.dist(samples[0]['position_xy_m'], samples[-1]['position_xy_m']) < 3:
            raise ValueError('Native ego did not move through turn')
        packet = {'case_id': case_id, 'approach_road_id': survey['approach_road_id'],
                  'destination_road_id': survey['destination_road_id'], 'maneuver': 'left_turn',
                  'driver_control': True, 'rate_hz': 20, 'samples': samples}
        trace_path = output / 'original-trace.json'
        with trace_path.open('x', encoding='utf-8') as stream:
            stream.write(json.dumps(packet, indent=2) + '\n')
        camera_path = output / 'original-camera-index.json'
        with camera_path.open('x', encoding='utf-8') as stream:
            stream.write(json.dumps({'case_id': case_id, 'channels': cameras}, indent=2) + '\n')
        return {'case_id': case_id, 'trace_path': str(trace_path),
                'trace_sha256': hashlib.sha256(trace_path.read_bytes()).hexdigest(),
                'camera_index_path': str(camera_path),
                'camera_index_sha256': hashlib.sha256(camera_path.read_bytes()).hexdigest(),
                'map_source_sha256': plan['survey_source_sha256'], 'frames': len(samples),
                'physical_acceptance_claimed': False}
    finally:
        try:
            if camera_source is not None:
                camera_source.close()
        finally:
            if ego is not None:
                try:
                    adapter.emergency_stop(ego)
                finally:
                    adapter.destroy(ego)

"""Acquire original CARLA RGB camera PNGs for an exact 20 Hz Native turn.

The camera poses are supplied by a reviewed survey. This lazy boundary owns
sensor actors and never generates an image when a callback is absent.
"""
from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path
from queue import Empty, Queue

CAMERAS = ('dash', 'front', 'left', 'right')
PROFILE = {'dash': (1920, 1080), 'front': (1280, 720),
           'left': (1280, 720), 'right': (1280, 720)}


class NativeCameraSource:
    def __init__(self, world, carla, survey_path, survey_sha256, output, *, dimensions=None,
                 timeout_s=3.0):
        raw = Path(survey_path).read_bytes()
        if hashlib.sha256(raw).hexdigest() != survey_sha256:
            raise ValueError('original camera survey packet hash differs')
        survey = json.loads(raw)
        if survey.get('cell_id') != 'C109705' or survey.get('maneuver') != 'left_turn':
            raise ValueError('original camera survey context differs')
        poses = survey.get('camera_poses')
        if not isinstance(poses, dict) or set(poses) != set(CAMERAS):
            raise ValueError('four source-surveyed camera poses required')
        if type(timeout_s) not in (int, float) or not math.isfinite(timeout_s) or timeout_s <= 0:
            raise ValueError('positive original camera timeout required')
        self.poses = poses
        self.world, self.carla = world, carla
        self.output = Path(output)
        self.dimensions = dict(PROFILE if dimensions is None else dimensions)
        if set(self.dimensions) != set(CAMERAS):
            raise ValueError('four original camera dimensions required')
        self.timeout_s = timeout_s
        self.sensors = {}
        self.queues = {name: Queue(maxsize=4) for name in CAMERAS}
        self.closed = False
        self.last_frame = None

    def configure_cameras(self, ego, channels, *, fps):
        if self.closed or self.sensors or tuple(channels) != CAMERAS or fps != 20:
            raise ValueError('exact original four-camera 20 Hz setup required')
        if self.output.exists() and any(self.output.iterdir()):
            raise ValueError('refusing to overwrite original camera sources')
        self.output.mkdir(parents=True, exist_ok=True)
        try:
            for name in CAMERAS:
                pose = self.poses[name]
                if not isinstance(pose, dict) or set(pose) != {'x', 'y', 'z', 'yaw', 'pitch', 'roll'}:
                    raise ValueError(f'original camera pose incomplete: {name}')
                if any(type(value) not in (int, float) or not math.isfinite(value)
                       for value in pose.values()):
                    raise ValueError(f'original camera pose nonfinite: {name}')
                width, height = self.dimensions[name]
                if type(width) is not int or type(height) is not int or width < 1 or height < 1:
                    raise ValueError('original camera dimensions invalid')
                blueprint = self.world.get_blueprint_library().find('sensor.camera.rgb')
                for key, value in (('image_size_x', width), ('image_size_y', height),
                                   ('sensor_tick', 0.05)):
                    blueprint.set_attribute(key, str(value))
                transform = self.carla.Transform(
                    self.carla.Location(x=pose['x'], y=pose['y'], z=pose['z']),
                    self.carla.Rotation(yaw=pose['yaw'], pitch=pose['pitch'], roll=pose['roll']))
                sensor = self.world.spawn_actor(blueprint, transform, attach_to=ego)
                self.sensors[name] = sensor
                queue = self.queues[name]
                sensor_id = sensor.id

                def on_image(image, *, target=queue, bound_id=sensor_id):
                    if not target.full():
                        target.put_nowait((bound_id, image))

                sensor.listen(on_image)
        except BaseException:
            self.close()
            raise

    def camera_frame(self, channel, frame):
        if self.closed or channel not in self.sensors or type(frame) is not int:
            raise ValueError('original camera channel or frame invalid')
        try:
            sensor_id, image = self.queues[channel].get(timeout=self.timeout_s)
        except Empty as exc:
            raise ValueError(f'original camera callback absent: {channel}') from exc
        if sensor_id != self.sensors[channel].id or getattr(image, 'frame', None) != frame:
            raise ValueError(f'original camera callback frame mismatch: {channel}')
        width, height = self.dimensions[channel]
        if getattr(image, 'width', None) != width or getattr(image, 'height', None) != height:
            raise ValueError(f'original camera dimensions differ: {channel}')
        path = self.output / channel / f'{frame:08d}.png'
        path.parent.mkdir(parents=True, exist_ok=True)
        if path.exists():
            raise ValueError('original camera frame overwrite refused')
        image.save_to_disk(str(path))
        if not path.is_file() or path.stat().st_size == 0:
            raise ValueError('original camera PNG missing after callback save')
        return {'frame': frame, 'channel': channel,
                'source_path': str(path.relative_to(self.output.parent)),
                'source_sha256': hashlib.sha256(path.read_bytes()).hexdigest()}

    def close(self):
        if self.closed:
            return
        self.closed = True
        errors = []
        for name in reversed(tuple(self.sensors)):
            try:
                self.sensors[name].stop()
                self.sensors[name].destroy()
            except BaseException as exc:
                errors.append(f'{name}: {exc}')
        if errors:
            raise RuntimeError('original camera cleanup failed: ' + '; '.join(errors))

"""Decode every source-bound original PNG frame for a four-camera attempt."""
from __future__ import annotations

import hashlib
from pathlib import Path

from PIL import Image, UnidentifiedImageError

CAMERAS = ('dash', 'front', 'left', 'right')
DELIVERY_SIZE = {'dash': (1920, 1080), 'front': (1280, 720),
                 'left': (1280, 720), 'right': (1280, 720)}


def decode(root, index, frames, *, delivery=False):
    """Require one distinct, complete PNG per channel and original Native tick.

    Hashes are checked against the camera index before full Pillow decoding.
    A diagnostic may use a small image size; delivery uses the capture profile.
    """
    root = Path(root).resolve()
    if set(index.get('channels', {})) != set(CAMERAS) or len(frames) != 900:
        raise ValueError('four-camera 900-frame PNG index required')
    dimensions = {}
    counts = {}
    for channel in CAMERAS:
        rows = index['channels'][channel]
        if not isinstance(rows, list) or len(rows) != 900:
            raise ValueError('900 original PNG frames required per channel')
        seen = set()
        for frame, row in zip(frames, rows):
            if row.get('frame') != frame or row.get('channel') != channel:
                raise ValueError('PNG frame/time/channel join differs')
            relative = row.get('source_path')
            if not isinstance(relative, str) or not relative or Path(relative).is_absolute() or any(
                    part in ('.', '..') for part in Path(relative).parts):
                raise ValueError('PNG source path escapes attempt')
            path = (root / relative).resolve()
            if not path.is_relative_to(root) or path.suffix.lower() != '.png' or not path.is_file():
                raise ValueError('original PNG source missing')
            if path in seen:
                raise ValueError('PNG source reused for multiple frames')
            seen.add(path)
            digest = hashlib.sha256(path.read_bytes()).hexdigest()
            if digest != row.get('source_sha256'):
                raise ValueError('original PNG source hash differs')
            try:
                with Image.open(path) as im:
                    if im.format != 'PNG' or im.mode not in ('RGB', 'RGBA'):
                        raise ValueError('original PNG format or color mode differs')
                    size = im.size
                    im.load()
            except (UnidentifiedImageError, OSError) as exc:
                raise ValueError('original PNG full decode failed') from exc
            if channel in dimensions and dimensions[channel] != size:
                raise ValueError('original PNG dimensions vary within channel')
            if delivery and size != DELIVERY_SIZE[channel]:
                raise ValueError('original PNG capture profile dimensions differ')
            dimensions[channel] = size
        counts[channel] = len(seen)
    return {'full_source_decode': True, 'decoded_frames': counts,
            'source_dimensions_px': {k: list(v) for k, v in dimensions.items()},
            'actual_pixels': True, 'visible_participants_verified': False}

"""Independent source-bound departure pair audit; leaves statutory judgment open."""
from __future__ import annotations

import argparse
import hashlib
import json
import math
from pathlib import Path


def _load(path):
    p = Path(path)
    if not p.is_file():
        raise ValueError('measurement report missing')
    return json.loads(p.read_text())


def _verified_source(source):
    path = Path(source['path'])
    if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest() != source['sha256']:
        raise ValueError('comparison source missing or hash differs')


def _original_approach(report):
    trace = _load(report['sources'][1]['path'])
    if trace.get('case_id') != report['case_id']:
        raise ValueError('comparison original trace case differs')
    samples = trace.get('samples')
    if not isinstance(samples, list):
        raise ValueError('comparison original approach samples missing')
    approach = []
    for sample in samples:
        if sample.get('phase') == 'intersection_entry':
            break
        if sample.get('phase') != 'approach' or sample.get('road_id') != report['approach_road_id']:
            raise ValueError('comparison original approach phase or road differs')
        xy = sample.get('position_xy_m')
        heading, speed = sample.get('heading_rad'), sample.get('speed_mps')
        if (not isinstance(xy, list) or len(xy) != 2 or
                any(type(x) not in (int, float) or not math.isfinite(x) for x in xy) or
                any(type(x) not in (int, float) or not math.isfinite(x) for x in (heading, speed)) or speed < 0):
            raise ValueError('comparison original approach measurement invalid')
        approach.append((xy, heading, speed))
    if len(approach) < 2 or len(approach) == len(samples):
        raise ValueError('comparison original approach or intersection entry missing')
    return approach


def audit(near_report, far_report, *, expected_near, expected_far, expected_centerline_kind):
    """Check measured pair isolation without a legal position threshold."""
    near = _load(near_report)
    far = _load(far_report)
    for report, expected in ((near, expected_near), (far, expected_far)):
        if report.get('case_id') != expected:
            raise ValueError('comparison case identity differs')
        if report.get('centerline_kind') != expected_centerline_kind:
            raise ValueError('comparison centerline convention differs')
        if report.get('statutory_position_judgment') is not None:
            raise ValueError('comparison cannot carry legal judgment')
        if report.get('sample_count', 0) < 1 or not report.get('per_frame'):
            raise ValueError('comparison original departure samples missing')
        if len(report.get('sources', [])) != 2:
            raise ValueError('comparison map and trace sources required')
        for source in report['sources']:
            _verified_source(source)
